/* ============================================================================
Merchant Sales-Based Financing Strategy Simulator
Module 2.8 — Servicing Execution Simulation, Payment Processing
             & Account Lifecycle Control

Program     : 194_MSBF_M2_8_Master_Report_v0_2.sql
Version     : v0.2

Purpose
-------
Produce one executive/governance row after formal acceptance, reconciling
lifecycle, accepted source identity, physical cardinalities, payment and
transition posture, evidence, non-production boundaries, archive reproduction,
stress diagnostics, and canonical identity.

Stage boundary
--------------
All servicing, payment, processor-reference, return, retry, and lifecycle
outputs are deterministic synthetic evidence. No real funds move; no bank or
routing data is used; no ACH/network transmission, external processor call,
merchant contact, write-off/collection/legal execution, external notice, or
production adverse action occurs.

Required result
---------------
overall_m2_8_status = PASS.
============================================================================ */

SET statement_timeout='35min';SET jit=off;
WITH r AS(SELECT run_id,run_code,run_version,run_status FROM msbf_ctl.run_registry WHERE run_code='M1_V0_2_BASELINE_BUILD' AND run_version=1),p AS(SELECT * FROM msbf_ctl.m2_8_policy_profile WHERE module1_run_id=(SELECT run_id FROM r)),g AS(SELECT * FROM msbf_ctl.m2_8_servicing_execution_contract_registry WHERE module1_run_id=(SELECT run_id FROM r)),a AS(SELECT result_status gate_status FROM msbf_ctl.acceptance_gate_result WHERE run_id=(SELECT run_id FROM r) AND gate_id='M2_8_SERVICING_EXECUTION_PAYMENT_LIFECYCLE_CONTROL' AND review_version=1),e AS(SELECT count(*) FILTER(WHERE evidence_code LIKE 'M2_8_POS_%' AND status='PASS') positive_passes,count(*) FILTER(WHERE evidence_code LIKE 'M2_8_POS_%') positive_checks,count(*) FILTER(WHERE evidence_code LIKE 'M2_8_NEG_%' AND status='PASS') negative_passes,count(*) FILTER(WHERE evidence_code LIKE 'M2_8_NEG_%') negative_checks,count(*) FILTER(WHERE evidence_code LIKE 'M2_8_%' AND evidence_code NOT LIKE 'M2_8_POS_%' AND evidence_code NOT LIKE 'M2_8_NEG_%' AND evidence_code<>'M2_8_ACCEPTANCE_SUMMARY') generation_evidence_rows,count(*) FILTER(WHERE evidence_code='M2_8_ACCEPTANCE_SUMMARY' AND status='PASS') acceptance_evidence_rows,count(*) FILTER(WHERE evidence_code LIKE 'M2_8_%' AND status='FAIL') failed_evidence_rows FROM msbf_ctl.run_evidence WHERE run_id=(SELECT run_id FROM r)),b AS(SELECT count(*) latest_rows,count(*) FILTER(WHERE no_processing_required_flag) no_processing_required_rows,count(*) FILTER(WHERE servicing_execution_outcome_code='SIMULATED_TEMPORARY_PAYMENT_PROCESSING_ACTIVE') temporary_processing_rows,count(*) FILTER(WHERE processing_review_required_flag) review_hold_rows,count(*) FILTER(WHERE processing_authorized_flag) processing_authorized_rows,round(sum(CASE WHEN processing_authorized_flag THEN source_exposure_amount ELSE 0 END),2) processing_authorized_amount,round(sum(CASE WHEN processing_review_required_flag THEN source_exposure_amount ELSE 0 END),2) review_hold_amount,sum(payment_event_count) payment_event_rows,sum(settled_event_count) settled_event_rows,sum(returned_event_count) returned_event_rows,sum(retry_event_count) retry_event_rows,max(standard_daily_payment_amount) standard_daily_payment_amount,max(temporary_daily_payment_amount) temporary_daily_payment_amount,round(sum(scheduled_payment_amount),2) scheduled_payment_amount,round(sum(processed_payment_amount),2) processed_payment_amount,round(sum(returned_payment_amount),2) returned_payment_amount,round(sum(retry_payment_amount),2) retry_payment_amount,round(sum(ending_simulated_exposure_amount),2) ending_simulated_exposure_amount FROM msbf_m2.application_servicing_execution_latest WHERE module1_run_id=(SELECT run_id FROM r)),y AS(SELECT count(*) payment_event_rows,min(event_date) first_event_date,max(event_date) last_event_date,count(*) FILTER(WHERE payment_status_code='SIMULATED_SETTLED') settled_event_rows,count(*) FILTER(WHERE payment_status_code='SIMULATED_RETURNED') returned_event_rows,count(*) FILTER(WHERE payment_status_code='SIMULATED_RETRY_SETTLED') retry_event_rows,max(standard_daily_payment_amount) standard_daily_payment_amount,max(applied_payment_factor) applied_payment_factor,max(scheduled_payment_amount) temporary_daily_payment_amount,round(sum(scheduled_payment_amount),2) scheduled_payment_amount,round(sum(processed_payment_amount),2) processed_payment_amount,round(sum(returned_payment_amount),2) returned_payment_amount,round(sum(retry_payment_amount),2) retry_payment_amount,min(simulated_outstanding_exposure_amount) active_ending_exposure_amount FROM msbf_m2.synthetic_payment_processing_event WHERE module1_run_id=(SELECT run_id FROM r)),t AS(SELECT count(*) lifecycle_transition_rows,count(*) FILTER(WHERE transition_sequence=0) initial_transition_rows,count(*) FILTER(WHERE transition_type_code IN ('PAYMENT_PROCESSING_EVENT','PAYMENT_RETURN_EVENT','PAYMENT_RETRY_EVENT')) payment_transition_rows,count(*) FILTER(WHERE transition_type_code='REASSESSMENT_CHECKPOINT') checkpoint_transition_rows,count(*) FILTER(WHERE lifecycle_state_after_code='CLOSED_NO_PROCESSING_REQUIRED' AND transition_sequence=0) closed_state_rows,count(*) FILTER(WHERE lifecycle_state_after_code='SERVICING_REVIEW_HOLD' AND transition_sequence=0) review_hold_state_rows,count(*) FILTER(WHERE lifecycle_state_after_code='REASSESSMENT_DUE') reassessment_due_rows FROM msbf_m2.account_lifecycle_transition_snapshot WHERE module1_run_id=(SELECT run_id FROM r)),d AS(SELECT
 (SELECT count(*) FROM msbf_m2.application_servicing_execution_snapshot WHERE module1_run_id=(SELECT run_id FROM r) AND (real_funds_moved_flag OR bank_account_data_present_flag OR ach_or_network_transmitted_flag OR external_processor_called_flag OR merchant_contact_executed_flag OR write_off_or_collection_flag OR external_notice_generated_flag OR production_adverse_action_flag))+
 (SELECT count(*) FROM msbf_m2.synthetic_payment_processing_event WHERE module1_run_id=(SELECT run_id FROM r) AND (real_funds_moved_flag OR bank_account_data_present_flag OR ach_or_network_transmitted_flag OR external_processor_called_flag OR merchant_contact_executed_flag OR external_notice_generated_flag OR production_adverse_action_flag))+
 (SELECT count(*) FROM msbf_m2.account_lifecycle_transition_snapshot WHERE module1_run_id=(SELECT run_id FROM r) AND (real_funds_moved_flag OR production_account_state_flag OR external_system_update_flag)) execution_boundary_rows,
 (SELECT canonical_entities FROM msbf_m2.v_m2_8_canonical_hash WHERE module1_run_id=(SELECT run_id FROM r)) physical_canonical_entities,
 (SELECT combined_set_hash FROM msbf_m2.v_m2_8_canonical_hash WHERE module1_run_id=(SELECT run_id FROM r)) physical_combined_set_hash,
 (SELECT count(*) FROM msbf_m2.v_m2_8_matched_scenario_comparison WHERE module1_run_id=(SELECT run_id FROM r) AND (stress_processing_permission_improvement_flag OR stress_priority_improvement_flag OR stress_exposure_improvement_flag)) stress_improvement_rows,
 (SELECT count(*) FROM msbf_m2.application_servicing_execution_latest latest FULL JOIN msbf_m2.application_servicing_execution_archive archive ON archive.module1_run_id=latest.module1_run_id AND archive.contract_version=latest.contract_version AND archive.scenario_id=latest.scenario_id AND archive.merchant_application_id=latest.merchant_application_id WHERE coalesce(latest.module1_run_id,archive.module1_run_id)=(SELECT run_id FROM r) AND (latest.contract_row_hash IS DISTINCT FROM archive.contract_row_hash OR archive.contract_payload IS DISTINCT FROM (to_jsonb(latest)-'created_at'))) archive_mismatches,
 (SELECT count(*) FROM information_schema.columns WHERE table_schema='msbf_m2' AND table_name IN ('application_servicing_execution_snapshot','synthetic_payment_processing_event','account_lifecycle_transition_snapshot','application_servicing_execution_latest','application_servicing_execution_archive') AND lower(column_name) IN ('real_bank_account_number','bank_account_number','routing_number','settlement_account_number','ach_trace_number','payment_network_confirmation','processor_authorization_code','external_notice_payload','production_adverse_action_notice')) prohibited_columns,
 (SELECT count(*) FROM information_schema.tables WHERE table_schema IN ('msbf_ctl','msbf_m2') AND lower(table_name) LIKE 'm2_9%') premature_m2_9_tables)
SELECT r.run_code,r.run_version,r.run_status,p.policy_code,p.policy_version,p.policy_status,p.methodology_version,p.contract_code,p.contract_version,p.schema_version,p.source_contract_code,p.source_contract_version,p.source_schema_version,p.source_acceptance_gate_id,p.source_combined_set_hash,p.configuration_hash,g.contract_status,a.gate_status,g.policy_rows,g.outcome_rows,g.action_rows,g.lifecycle_state_rows,g.reason_rows,g.source_rows,g.execution_rows,g.payment_event_rows,g.lifecycle_transition_rows,g.portfolio_summary_rows,g.latest_rows,g.archive_rows,g.comparison_rows,g.registry_rows,g.canonical_entities,b.no_processing_required_rows,b.temporary_processing_rows,b.review_hold_rows,b.processing_authorized_rows,b.processing_authorized_amount,b.review_hold_amount,y.payment_event_rows physical_payment_event_rows,y.settled_event_rows,y.returned_event_rows,y.retry_event_rows,y.first_event_date,y.last_event_date,y.standard_daily_payment_amount,y.applied_payment_factor,y.temporary_daily_payment_amount,y.scheduled_payment_amount,y.processed_payment_amount,y.returned_payment_amount,y.retry_payment_amount,y.active_ending_exposure_amount,b.ending_simulated_exposure_amount portfolio_ending_exposure_amount,t.lifecycle_transition_rows physical_lifecycle_transition_rows,t.initial_transition_rows,t.payment_transition_rows,t.checkpoint_transition_rows,t.closed_state_rows,t.review_hold_state_rows,t.reassessment_due_rows,e.positive_passes,e.positive_checks,e.negative_passes,e.negative_checks,e.generation_evidence_rows,e.acceptance_evidence_rows,e.failed_evidence_rows,d.execution_boundary_rows,d.physical_canonical_entities,d.stress_improvement_rows,d.archive_mismatches,d.prohibited_columns,d.premature_m2_9_tables,g.policy_set_hash,g.outcome_set_hash,g.action_set_hash,g.lifecycle_state_set_hash,g.reason_set_hash,g.source_set_hash,g.execution_set_hash,g.payment_event_set_hash,g.lifecycle_transition_set_hash,g.portfolio_summary_set_hash,g.latest_set_hash,g.archive_set_hash,g.contract_set_hash,g.combined_set_hash,
CASE WHEN r.run_status='M2_8_ACCEPTED' AND p.policy_status='APPROVED' AND g.contract_status='ACCEPTED' AND a.gate_status='PASS' AND g.policy_rows=1 AND g.outcome_rows=7 AND g.action_rows=7 AND g.lifecycle_state_rows=7 AND g.reason_rows=32 AND g.source_rows=59 AND g.execution_rows=59 AND g.payment_event_rows=7 AND g.lifecycle_transition_rows=67 AND g.portfolio_summary_rows=2 AND g.latest_rows=59 AND g.archive_rows=59 AND g.comparison_rows=15 AND g.registry_rows=1 AND g.canonical_entities=367 AND b.no_processing_required_rows=57 AND b.temporary_processing_rows=1 AND b.review_hold_rows=1 AND b.processing_authorized_rows=1 AND b.processing_authorized_amount=518.04 AND b.review_hold_amount=461.69 AND y.payment_event_rows=7 AND y.settled_event_rows=5 AND y.returned_event_rows=1 AND y.retry_event_rows=1 AND y.first_event_date=DATE '2026-07-24' AND y.last_event_date=DATE '2026-07-30' AND y.standard_daily_payment_amount=37 AND y.applied_payment_factor=.75 AND y.temporary_daily_payment_amount=27.75 AND y.scheduled_payment_amount=194.25 AND y.processed_payment_amount=194.25 AND y.returned_payment_amount=27.75 AND y.retry_payment_amount=27.75 AND y.active_ending_exposure_amount=323.79 AND b.ending_simulated_exposure_amount=785.48 AND t.lifecycle_transition_rows=67 AND t.initial_transition_rows=59 AND t.payment_transition_rows=7 AND t.checkpoint_transition_rows=1 AND t.closed_state_rows=57 AND t.review_hold_state_rows=1 AND t.reassessment_due_rows=1 AND e.positive_passes=120 AND e.positive_checks=120 AND e.negative_passes=20 AND e.negative_checks=20 AND e.generation_evidence_rows=24 AND e.acceptance_evidence_rows=1 AND e.failed_evidence_rows=0 AND d.execution_boundary_rows=0 AND d.physical_canonical_entities=367 AND g.combined_set_hash IS NOT DISTINCT FROM d.physical_combined_set_hash AND d.stress_improvement_rows=0 AND d.archive_mismatches=0 AND d.prohibited_columns=0 AND d.premature_m2_9_tables=0 THEN 'PASS' ELSE 'FAIL' END overall_m2_8_status
FROM r CROSS JOIN p CROSS JOIN g CROSS JOIN a CROSS JOIN e CROSS JOIN b CROSS JOIN y CROSS JOIN t CROSS JOIN d;
